export type ParsedWrapperProvideLiquidityInstruction<
  TProgram extends string = typeof EXPONENT_CLMM_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    depositor: TAccountMetas[0];
    market: TAccountMetas[1];
    ticks: TAccountMetas[2];
    /** PT liquidity account */
    tokenPtEscrow: TAccountMetas[3];
    /** YT liquidity account */
    tokenYtEscrow: TAccountMetas[4];
    /** SY token account owned by the market */
    tokenSyEscrow: TAccountMetas[5];
    /** Token account for SY owned by the depositor */
    tokenSyDepositor: TAccountMetas[6];
    /** Token account for YT owned by the depositor */
    tokenYtDepositor: TAccountMetas[7];
    /** Token account for PT owned by the depositor */
    tokenPtDepositor: TAccountMetas[8];
    mintYt: TAccountMetas[9];
    mintPt: TAccountMetas[10];
    tokenProgram: TAccountMetas[11];
    marketAddressLookupTable: TAccountMetas[12];
    syProgram: TAccountMetas[13];
    exponentCoreProgram: TAccountMetas[14];
    lpPosition: TAccountMetas[15];
    instructionsSysvar: TAccountMetas[16];
    systemProgram: TAccountMetas[17];
    rent: TAccountMetas[18];
    eventAuthority: TAccountMetas[19];
    program: TAccountMetas[20];
  };
  data: WrapperProvideLiquidityInstructionData;
};

export function parseWrapperProvideLiquidityInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedWrapperProvideLiquidityInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 21) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 21,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      depositor: getNextAccount(),
      market: getNextAccount(),
      ticks: getNextAccount(),
      tokenPtEscrow: getNextAccount(),
      tokenYtEscrow: getNextAccount(),
      tokenSyEscrow: getNextAccount(),
      tokenSyDepositor: getNextAccount(),
      tokenYtDepositor: getNextAccount(),
      tokenPtDepositor: getNextAccount(),
      mintYt: getNextAccount(),
      mintPt: getNextAccount(),
      tokenProgram: getNextAccount(),
      marketAddressLookupTable: getNextAccount(),
      syProgram: getNextAccount(),
      exponentCoreProgram: getNextAccount(),
      lpPosition: getNextAccount(),
      instructionsSysvar: getNextAccount(),
      systemProgram: getNextAccount(),
      rent: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getWrapperProvideLiquidityInstructionDataDecoder().decode(instruction.data),
  };
}
